//! The video project format (R-V1): what a project folder holds, how every
//! piece is validated before it is written, and how the core generates the
//! composition root (`index.html`) from `video.json`.
//!
//! A project folder (see `docs/VIDEO.md` and the shared contract §1):
//!
//! ```text
//! video.json                 our metadata: title, aspect, fps, scenes (order
//!                            and durations), variables (and their values),
//!                            voice/music tracks, template id
//! index.html                 GENERATED by the core from video.json (never
//!                            written by the model or the renderer)
//! theme.css                  optional shared CSS (fonts, palette), inlined
//!                            into index.html
//! compositions/<scene>.html  one HyperFrames scene each, `<template>` wrapped
//! assets/...                 images, audio, fonts (fonts in assets/fonts/)
//! exports/...                MP4s downloaded from the render service (never
//!                            part of the render bundle)
//! ```
//!
//! Generating `index.html` keeps the timing and the wiring correct by
//! construction: scene order and durations live in `video.json`, so the
//! editor's reorder / duration changes and the model's edits can never leave
//! a host whose id differs from its scene, a root shorter than its last clip,
//! or a variable the form cannot show.
//!
//! The scene rules encode the HyperFrames authoring contract for a
//! deterministic, server-rendered film: no network (every URL is a relative
//! `assets/` file or a `data:` URI), no GSAP (license), CSS/WAAPI animation
//! only, no clocks/randomness/timers, finite animations, no manual media
//! control. They are checked here, synchronously, so the model gets the
//! errors back in its tool result; the official `@hyperframes/lint` runs in
//! the renderer on top (see `src/video/lint.ts`).

use serde::{Deserialize, Serialize};

use crate::tools::website::{self, UrlPolicy};

/// The HyperFrames release this format, the player, the lint and the server
/// renderer are pinned to (one coordinated version).
pub const HYPERFRAMES_VERSION: &str = "0.9.86";

/// The `video.json` format version.
pub const FORMAT_VERSION: u32 = 1;

/// Longest video (contract §1).
pub const MAX_DURATION_S: f64 = 600.0;
/// Shortest and longest scene.
pub const MIN_SCENE_S: f64 = 0.5;
pub const MAX_SCENE_S: f64 = 120.0;
/// Most scenes per video.
pub const MAX_SCENES: usize = 24;
/// Most variables per video.
pub const MAX_VARIABLES: usize = 24;
/// Largest scene file.
pub const MAX_SCENE_BYTES: usize = 512 * 1024;
/// Largest `theme.css`.
pub const MAX_THEME_BYTES: usize = 256 * 1024;
/// Longest title and variable label (characters).
pub const MAX_TITLE_CHARS: usize = 120;
pub const MAX_LABEL_CHARS: usize = 60;
/// Longest text variable value (characters).
pub const MAX_TEXT_CHARS: usize = 400;
/// The frame rates the renderer accepts.
pub const FPS_CHOICES: [u32; 4] = [24, 25, 30, 60];

/// The three canvases of v1 (contract §1 limits).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum Aspect {
    #[serde(rename = "16:9")]
    Landscape,
    #[serde(rename = "9:16")]
    Portrait,
    #[serde(rename = "1:1")]
    Square,
}

impl Aspect {
    pub fn parse(raw: &str) -> Option<Self> {
        match raw.trim() {
            "16:9" => Some(Self::Landscape),
            "9:16" => Some(Self::Portrait),
            "1:1" => Some(Self::Square),
            _ => None,
        }
    }

    /// Canvas size in pixels.
    pub fn size(self) -> (u32, u32) {
        match self {
            Self::Landscape => (1920, 1080),
            Self::Portrait => (1080, 1920),
            Self::Square => (1080, 1080),
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Self::Landscape => "16:9",
            Self::Portrait => "9:16",
            Self::Square => "1:1",
        }
    }
}

/// What a variable holds, which decides its form field.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum VariableKind {
    /// A text (`data-var-text`).
    Text,
    /// A `#rrggbb` color (`var(--id)` in CSS).
    Color,
    /// An image file in `assets/` (`data-var-src`), or empty for none.
    Image,
}

/// One fill-in field of the video (the editor's variables form).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Variable {
    pub id: String,
    #[serde(rename = "type")]
    pub kind: VariableKind,
    pub label: String,
    /// The current value (the composition's declared default, so the render
    /// needs no extra input).
    pub value: String,
}

/// One scene: its file is `compositions/<id>.html`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Scene {
    pub id: String,
    pub title: String,
    /// Seconds.
    pub duration: f64,
}

/// A voice-over or music track (one file in `assets/`).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AudioTrack {
    /// `assets/<name>`.
    pub file: String,
    /// Gain, 0..=1.
    pub volume: f64,
    /// The file's length in seconds when known (voice-overs: always).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub duration: Option<f64>,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Audio {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub voice: Option<AudioTrack>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub music: Option<AudioTrack>,
}

/// `video.json`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct VideoMeta {
    pub format: u32,
    pub hyperframes: String,
    pub title: String,
    pub aspect: Aspect,
    pub fps: u32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub template: Option<String>,
    pub scenes: Vec<Scene>,
    #[serde(default)]
    pub variables: Vec<Variable>,
    #[serde(default)]
    pub audio: Audio,
}

impl VideoMeta {
    pub fn new(title: &str, aspect: Aspect, fps: u32) -> Self {
        Self {
            format: FORMAT_VERSION,
            hyperframes: HYPERFRAMES_VERSION.to_string(),
            title: title.to_string(),
            aspect,
            fps,
            template: None,
            scenes: Vec::new(),
            variables: Vec::new(),
            audio: Audio::default(),
        }
    }

    /// Total length in seconds (the scenes back to back).
    pub fn duration(&self) -> f64 {
        round_ms(self.scenes.iter().map(|scene| scene.duration).sum())
    }

    /// Each scene's start, in order.
    pub fn starts(&self) -> Vec<f64> {
        let mut at = 0.0;
        self.scenes
            .iter()
            .map(|scene| {
                let start = round_ms(at);
                at += scene.duration;
                start
            })
            .collect()
    }
}

/// Seconds rounded to the millisecond (no float noise in the markup).
pub fn round_ms(seconds: f64) -> f64 {
    (seconds * 1000.0).round() / 1000.0
}

/// A number as the markup writes it: `4`, `2.5`, `0.125`.
pub fn fmt_seconds(seconds: f64) -> String {
    let text = format!("{:.3}", round_ms(seconds));
    let text = text.trim_end_matches('0').trim_end_matches('.');
    if text.is_empty() || text == "-0" {
        "0".into()
    } else {
        text.to_string()
    }
}

// ------------------------------------------------------------ names --

/// A scene or variable id: `[a-z][a-z0-9-]{0,31}` (also a CSS custom
/// property name and an element id prefix).
pub fn valid_id(id: &str) -> bool {
    let bytes = id.as_bytes();
    !bytes.is_empty()
        && bytes.len() <= 32
        && bytes[0].is_ascii_lowercase()
        && bytes
            .iter()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || *b == b'-')
        && !id.ends_with('-')
        // Reserved: the root composition and the managed audio clips.
        && !matches!(id, "main" | "root" | "voiceover" | "music")
}

/// The kinds of asset a project may hold, by extension.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AssetKind {
    Image,
    Audio,
    Video,
    Font,
}

/// Allowed asset extensions and their MIME type.
pub const ASSET_TYPES: &[(&str, &str, AssetKind)] = &[
    ("png", "image/png", AssetKind::Image),
    ("jpg", "image/jpeg", AssetKind::Image),
    ("jpeg", "image/jpeg", AssetKind::Image),
    ("webp", "image/webp", AssetKind::Image),
    ("gif", "image/gif", AssetKind::Image),
    ("svg", "image/svg+xml", AssetKind::Image),
    ("mp3", "audio/mpeg", AssetKind::Audio),
    ("wav", "audio/wav", AssetKind::Audio),
    ("m4a", "audio/mp4", AssetKind::Audio),
    ("ogg", "audio/ogg", AssetKind::Audio),
    ("mp4", "video/mp4", AssetKind::Video),
    ("webm", "video/webm", AssetKind::Video),
    ("woff2", "font/woff2", AssetKind::Font),
    ("woff", "font/woff", AssetKind::Font),
    ("ttf", "font/ttf", AssetKind::Font),
    ("otf", "font/otf", AssetKind::Font),
];

/// The extension of a file name, lowercased.
pub fn extension(name: &str) -> Option<String> {
    let (stem, ext) = name.rsplit_once('.')?;
    (!stem.is_empty()).then(|| ext.to_ascii_lowercase())
}

/// The MIME type and kind of an asset name, when its extension is allowed.
pub fn asset_type(name: &str) -> Option<(&'static str, AssetKind)> {
    let ext = extension(name)?;
    ASSET_TYPES
        .iter()
        .find(|(known, _, _)| *known == ext)
        .map(|(_, mime, kind)| (*mime, *kind))
}

/// A file name inside `assets/` (or `assets/fonts/`): lowercase ASCII
/// letters, digits, `-`, `_` and one extension dot, at most 64 bytes, with
/// an allowed extension.
pub fn valid_asset_file_name(name: &str) -> bool {
    let bytes = name.as_bytes();
    !bytes.is_empty()
        && bytes.len() <= 64
        && (bytes[0].is_ascii_lowercase() || bytes[0].is_ascii_digit())
        && bytes.iter().all(|b| {
            b.is_ascii_lowercase() || b.is_ascii_digit() || matches!(b, b'-' | b'_' | b'.')
        })
        && name.matches('.').count() == 1
        && asset_type(name).is_some()
}

/// A project-relative asset path: `assets/<name>` or `assets/fonts/<name>`.
/// Nothing else (no other folder, no `..`, no absolute path) is an asset.
pub fn valid_asset_path(path: &str) -> bool {
    let Some(rest) = path.strip_prefix("assets/") else {
        return false;
    };
    match rest.strip_prefix("fonts/") {
        Some(font) => {
            valid_asset_file_name(font) && matches!(asset_type(font), Some((_, AssetKind::Font)))
        }
        None => valid_asset_file_name(rest),
    }
}

// -------------------------------------------------------- the checks --

/// Whether a URL attribute value stays inside a video project: empty, a
/// fragment, a `data:` URI, or a relative asset path.
fn video_local_value(_name: &str, value: &str) -> bool {
    let v = value.trim();
    let low = v.to_ascii_lowercase();
    v.is_empty()
        || v.starts_with('#')
        || low.starts_with("data:")
        || valid_asset_path(v.strip_prefix("./").unwrap_or(v))
}

/// Whether a CSS `url(` target (lowercased, trimmed) stays inside the
/// project.
fn video_css_url_local(rest: &str) -> bool {
    if rest.starts_with("data:") || rest.starts_with('#') {
        return true;
    }
    let end = rest
        .find(|c: char| c == ')' || c == '"' || c == '\'' || c.is_whitespace())
        .unwrap_or(rest.len());
    let target = &rest[..end];
    valid_asset_path(target.strip_prefix("./").unwrap_or(target))
}

fn video_refused(what: &str) -> String {
    format!(
        "{what}. A video loads nothing from the network: use files in assets/ \
         (relative paths like assets/logo.png) or data: URIs."
    )
}

const VIDEO_POLICY: UrlPolicy = UrlPolicy {
    local_value: video_local_value,
    css_url_local: video_css_url_local,
    refused: video_refused,
};

/// Tags a video document may not contain.
const FORBIDDEN_TAGS: &[&str] = &[
    "iframe", "object", "embed", "form", "link", "base", "meta", "frame", "frameset", "applet",
    "portal",
];

/// Script text that makes a film non-deterministic, reaches outside the
/// page, or drives media by hand (lowercased needles).
const FORBIDDEN_SCRIPT: &[(&str, &str)] = &[
    (
        "gsap",
        "GSAP is not allowed: animate with CSS @keyframes or the Web Animations API",
    ),
    (
        "date.now",
        "Date.now() is not allowed: animation must depend only on the time",
    ),
    (
        "new date()",
        "new Date() is not allowed: animation must depend only on the time",
    ),
    (
        "performance.now",
        "performance.now() is not allowed: animation must depend only on the time",
    ),
    (
        "math.random",
        "Math.random() is not allowed: use a seeded generator (for example mulberry32 with a fixed seed)",
    ),
    (
        "settimeout",
        "timers are not allowed: animation must depend only on the time",
    ),
    (
        "setinterval",
        "timers are not allowed: animation must depend only on the time",
    ),
    (
        "requestanimationframe",
        "requestAnimationFrame loops are not allowed: use CSS animations or WAAPI",
    ),
    ("fetch(", "fetch is not allowed: a video loads nothing"),
    (
        "xmlhttprequest",
        "XMLHttpRequest is not allowed: a video loads nothing",
    ),
    (
        "websocket",
        "WebSocket is not allowed: a video loads nothing",
    ),
    (
        "eventsource",
        "EventSource is not allowed: a video loads nothing",
    ),
    ("import(", "dynamic import is not allowed"),
    ("localstorage", "storage is not allowed"),
    ("sessionstorage", "storage is not allowed"),
    ("indexeddb", "storage is not allowed"),
    ("document.cookie", "cookies are not allowed"),
    ("eval(", "eval is not allowed"),
    ("new function", "new Function is not allowed"),
    (".play(", "never call play() on media: the runtime plays it"),
    (
        "currenttime",
        "never set currentTime: the runtime seeks media",
    ),
    ("window.open", "window.open is not allowed"),
    ("location.", "navigation is not allowed"),
    ("location=", "navigation is not allowed"),
    ("location =", "navigation is not allowed"),
];

/// A scene file, validated and normalized: the `<template>` carries the id
/// the runtime looks up, and the scene root opts out of the timeline wait.
pub fn validate_scene(id: &str, html: &str) -> Result<String, String> {
    if !valid_id(id) {
        return Err(format!(
            "scene id \"{id}\" is invalid: use lowercase letters, digits and dashes, starting with a letter (max 32)"
        ));
    }
    let text = check_text(html, MAX_SCENE_BYTES, "the scene")?;
    let trimmed = text.trim();
    let low = trimmed.to_ascii_lowercase();
    if !low.starts_with("<template") || !low.ends_with("</template>") {
        return Err(format!(
            "scene \"{id}\" must be ONE <template> element: start with <template id=\"{id}-template\"> and end with </template>; put its <style>, markup and any <script> inside"
        ));
    }
    if low.matches("<template").count() != 1 {
        return Err(format!(
            "scene \"{id}\" must contain exactly one <template> element"
        ));
    }
    let normalized = normalize_template_tag(trimmed, id);
    let normalized = ensure_root_no_timeline(&normalized, id)?;
    check_document_rules(&normalized).map_err(|message| format!("scene \"{id}\": {message}"))?;
    Ok(normalized)
}

/// The text checks shared by every file.
fn check_text<'a>(text: &'a str, cap: usize, what: &str) -> Result<&'a str, String> {
    if text.trim().is_empty() {
        return Err(format!("{what} is empty"));
    }
    if text.len() > cap {
        return Err(format!(
            "{what} is {} bytes; the limit is {cap}",
            text.len()
        ));
    }
    if text.contains('\0') {
        return Err(format!("{what} contains NUL bytes"));
    }
    Ok(text)
}

/// Rewrite the opening `<template ...>` to exactly `<template
/// id="<id>-template">` (the runtime mounts a scene from the inline
/// template with that id; other attributes mean nothing on it).
fn normalize_template_tag(html: &str, id: &str) -> String {
    let end = html.find('>').map_or(html.len(), |at| at + 1);
    format!("<template id=\"{id}-template\">{}", &html[end..])
}

/// The scene root (`data-composition-id="<id>"`) must exist; it gets
/// `data-no-timeline` when missing (CSS/WAAPI scenes register no GSAP
/// timeline, and without it every render waits 45 s per scene).
fn ensure_root_no_timeline(html: &str, id: &str) -> Result<String, String> {
    let low = html.to_ascii_lowercase();
    let mut found = None;
    for quote in ['"', '\''] {
        let needle = format!("data-composition-id={quote}{id}{quote}");
        if let Some(at) = low.find(&needle) {
            found = Some((at, needle.len()));
            break;
        }
    }
    let Some((at, len)) = found else {
        return Err(format!(
            "scene \"{id}\" needs a root element inside the template with data-composition-id=\"{id}\" (for example <div id=\"root\" data-composition-id=\"{id}\" data-width=\"...\" data-height=\"...\">)"
        ));
    };
    let tag_start = low[..at].rfind('<').unwrap_or(0);
    let tag_end = low[at..].find('>').map_or(low.len(), |end| at + end);
    if low[tag_start..tag_end].contains("data-no-timeline") {
        return Ok(html.to_string());
    }
    let insert = at + len;
    Ok(format!(
        "{} data-no-timeline{}",
        &html[..insert],
        &html[insert..]
    ))
}

/// Network, tag, script and CSS rules of a scene document.
fn check_document_rules(html: &str) -> Result<(), String> {
    website::check_network(html, &VIDEO_POLICY)?;
    let low = html.to_ascii_lowercase();
    website::for_each_tag(html, &low, |name, attributes| {
        if FORBIDDEN_TAGS.contains(&name) {
            return Err(format!("<{name}> is not allowed in a video"));
        }
        let has = |attr: &str| attributes.iter().any(|(n, _)| *n == attr);
        let value = |attr: &str| {
            attributes
                .iter()
                .find(|(n, _)| *n == attr)
                .map(|(_, v)| v.trim().to_ascii_lowercase())
        };
        if name == "script" && has("src") {
            return Err("scripts must be inline (<script> without src)".into());
        }
        if name == "script" && value("type").is_some_and(|t| t == "module" || t == "importmap") {
            return Err("module scripts are not allowed: use a classic inline <script>".into());
        }
        if has("crossorigin") {
            return Err("remove the crossorigin attribute: it breaks the preview".into());
        }
        if name == "audio" && !has("id") {
            return Err("every <audio> needs an id".into());
        }
        if name == "video" && !(has("muted") || value("data-has-audio").as_deref() == Some("true"))
        {
            return Err("a <video> needs muted (silent footage) or data-has-audio=\"true\"".into());
        }
        if (name == "audio" || name == "video")
            && (has("autoplay") || has("loop") || has("controls"))
        {
            return Err(format!(
                "<{name}> may not use autoplay, loop or controls: the runtime plays it"
            ));
        }
        if attributes.iter().any(|(n, _)| n.starts_with("on")) {
            return Err(format!(
                "inline event handlers ({}) are not allowed",
                attributes
                    .iter()
                    .find(|(n, _)| n.starts_with("on"))
                    .map_or("", |(n, _)| n)
            ));
        }
        if let Some(style) = value("style")
            && style.contains("infinite")
        {
            return Err("animations must be finite: no infinite iteration count".into());
        }
        Ok(())
    })?;
    for script in blocks(&low, "<script", "</script>") {
        for (needle, why) in FORBIDDEN_SCRIPT {
            if script.contains(needle) {
                return Err((*why).to_string());
            }
        }
    }
    for style in blocks(&low, "<style", "</style>") {
        check_css_rules(style)?;
    }
    Ok(())
}

/// The CSS rules: finite animations, nothing loaded.
fn check_css_rules(low_css: &str) -> Result<(), String> {
    if low_css.contains("infinite") {
        return Err(
            "animations must be finite: replace `infinite` with a number of iterations that fits the scene"
                .into(),
        );
    }
    if low_css.contains("expression(") || low_css.contains("-moz-binding") {
        return Err("legacy CSS script hooks are not allowed".into());
    }
    Ok(())
}

/// The bodies between `open` and `close` in a lowercased document.
fn blocks<'a>(low: &'a str, open: &str, close: &str) -> Vec<&'a str> {
    let mut out = Vec::new();
    let mut i = 0;
    while let Some(at) = low[i..].find(open) {
        let start = i + at;
        let body_start = low[start..]
            .find('>')
            .map_or(low.len(), |end| start + end + 1);
        let body_end = low[body_start..]
            .find(close)
            .map_or(low.len(), |end| body_start + end);
        out.push(&low[body_start..body_end]);
        i = body_end.max(start + open.len());
        if i >= low.len() {
            break;
        }
    }
    out
}

/// `theme.css`: shared CSS (fonts, palette) inlined into `index.html`.
pub fn validate_theme(css: &str) -> Result<String, String> {
    if css.trim().is_empty() {
        return Ok(String::new());
    }
    let text = check_text(css, MAX_THEME_BYTES, "theme.css")?;
    let low = text.to_ascii_lowercase();
    if low.contains("</style") || low.contains("<script") || low.contains("<!--") {
        return Err("theme.css must be plain CSS (no HTML)".into());
    }
    // Reuse the document checks on a wrapped copy (@import, url()).
    let wrapped = format!("<style>{text}</style>");
    website::check_network(&wrapped, &VIDEO_POLICY)?;
    check_css_rules(&low)?;
    Ok(text.to_string())
}

/// A `#rgb` / `#rrggbb` / `#rrggbbaa` color.
pub fn valid_color(value: &str) -> bool {
    let Some(hex) = value.strip_prefix('#') else {
        return false;
    };
    matches!(hex.len(), 3 | 6 | 8) && hex.bytes().all(|b| b.is_ascii_hexdigit())
}

/// A trimmed, whitespace-collapsed title within the cap (`None` if empty).
pub fn clean_title(raw: &str) -> Option<String> {
    let title: String = raw
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .chars()
        .filter(|c| !c.is_control())
        .take(MAX_TITLE_CHARS)
        .collect();
    (!title.is_empty()).then_some(title)
}

/// A variable value, validated for its kind. `has_asset` says whether an
/// `assets/` path exists in the project (image values must).
pub fn check_value(
    kind: VariableKind,
    value: &str,
    has_asset: &dyn Fn(&str) -> bool,
) -> Result<String, String> {
    match kind {
        VariableKind::Text => {
            if value.contains('\0') {
                return Err("text contains NUL bytes".into());
            }
            let count = value.chars().count();
            if count > MAX_TEXT_CHARS {
                return Err(format!(
                    "text is {count} characters; the limit is {MAX_TEXT_CHARS}"
                ));
            }
            Ok(value.to_string())
        }
        VariableKind::Color => {
            let color = value.trim().to_ascii_lowercase();
            if valid_color(&color) {
                Ok(color)
            } else {
                Err(format!("\"{value}\" is not a color like #ff5a1f"))
            }
        }
        VariableKind::Image => {
            let path = value.trim();
            if path.is_empty() {
                return Ok(String::new());
            }
            let image =
                valid_asset_path(path) && matches!(asset_type(path), Some((_, AssetKind::Image)));
            if !image || !has_asset(path) {
                return Err(format!(
                    "\"{value}\" is not an image file of this project (assets/<name>.png|jpg|webp|svg|gif)"
                ));
            }
            Ok(path.to_string())
        }
    }
}

/// The whole `video.json` model: names, limits and references.
pub fn validate_meta(meta: &VideoMeta, has_asset: &dyn Fn(&str) -> bool) -> Result<(), String> {
    if clean_title(&meta.title).as_deref() != Some(meta.title.as_str()) {
        return Err("the title is empty or not normalized".into());
    }
    if !FPS_CHOICES.contains(&meta.fps) {
        return Err(format!(
            "fps must be one of 24, 25, 30 or 60 (got {})",
            meta.fps
        ));
    }
    if meta.scenes.is_empty() {
        return Err("a video needs at least one scene".into());
    }
    if meta.scenes.len() > MAX_SCENES {
        return Err(format!("a video has at most {MAX_SCENES} scenes"));
    }
    let mut seen = std::collections::BTreeSet::new();
    for scene in &meta.scenes {
        if !valid_id(&scene.id) {
            return Err(format!("scene id \"{}\" is invalid", scene.id));
        }
        if !seen.insert(scene.id.as_str()) {
            return Err(format!("scene id \"{}\" is used twice", scene.id));
        }
        if !(MIN_SCENE_S..=MAX_SCENE_S).contains(&scene.duration) || !scene.duration.is_finite() {
            return Err(format!(
                "scene \"{}\" lasts {} s; a scene lasts {MIN_SCENE_S} to {MAX_SCENE_S} s",
                scene.id, scene.duration
            ));
        }
        if scene.title.chars().count() > MAX_LABEL_CHARS || scene.title.contains('\0') {
            return Err(format!(
                "scene \"{}\" has a title that is too long",
                scene.id
            ));
        }
    }
    if meta.duration() > MAX_DURATION_S {
        return Err(format!(
            "the video lasts {} s; the limit is {MAX_DURATION_S} s (10 minutes)",
            fmt_seconds(meta.duration())
        ));
    }
    if meta.variables.len() > MAX_VARIABLES {
        return Err(format!("a video has at most {MAX_VARIABLES} variables"));
    }
    let mut var_ids = std::collections::BTreeSet::new();
    for variable in &meta.variables {
        if !valid_id(&variable.id) {
            return Err(format!("variable id \"{}\" is invalid", variable.id));
        }
        if !var_ids.insert(variable.id.as_str()) {
            return Err(format!("variable id \"{}\" is used twice", variable.id));
        }
        if variable.label.trim().is_empty()
            || variable.label.chars().count() > MAX_LABEL_CHARS
            || variable.label.contains('\0')
        {
            return Err(format!("variable \"{}\" needs a short label", variable.id));
        }
        let checked = check_value(variable.kind, &variable.value, has_asset)
            .map_err(|err| format!("variable \"{}\": {err}", variable.id))?;
        if checked != variable.value {
            return Err(format!("variable \"{}\" is not normalized", variable.id));
        }
    }
    for track in [&meta.audio.voice, &meta.audio.music].into_iter().flatten() {
        let audio = valid_asset_path(&track.file)
            && matches!(asset_type(&track.file), Some((_, AssetKind::Audio)));
        if !audio || !has_asset(&track.file) {
            return Err(format!(
                "{} is not an audio file of this project",
                track.file
            ));
        }
        if !(0.0..=1.0).contains(&track.volume) || !track.volume.is_finite() {
            return Err("an audio volume is between 0 and 1".into());
        }
    }
    Ok(())
}

// ------------------------------------------------- index.html output --

/// Escape text for an HTML attribute value or element content.
pub fn escape_html(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            c => out.push(c),
        }
    }
    out
}

/// The HyperFrames declaration of the video's variables
/// (`data-composition-variables` on `<html>`): each value is the default.
fn variable_declarations(meta: &VideoMeta) -> serde_json::Value {
    serde_json::Value::Array(
        meta.variables
            .iter()
            .map(|variable| {
                let kind = match variable.kind {
                    VariableKind::Text => "string",
                    VariableKind::Color => "color",
                    VariableKind::Image => "image",
                };
                serde_json::json!({
                    "id": variable.id,
                    "type": kind,
                    "label": variable.label,
                    "default": variable.value,
                })
            })
            .collect(),
    )
}

/// Every variable's value by id (each scene host's `data-variable-values`,
/// so every mounted scene sees them in its own scope).
fn variable_values(meta: &VideoMeta) -> serde_json::Value {
    serde_json::Value::Object(
        meta.variables
            .iter()
            .map(|variable| {
                (
                    variable.id.clone(),
                    serde_json::Value::String(variable.value.clone()),
                )
            })
            .collect(),
    )
}

/// The managed audio clip for a track, ending with the video.
fn audio_clip(id: &str, track: &AudioTrack, total: f64, lane: u32) -> String {
    let duration = track.duration.map_or(total, |len| len.min(total));
    format!(
        "    <audio id=\"{id}\" class=\"clip\" src=\"{}\" data-start=\"0\" data-duration=\"{}\" data-track-index=\"{lane}\" data-volume=\"{}\"></audio>\n",
        escape_html(&track.file),
        fmt_seconds(duration),
        fmt_seconds(track.volume)
    )
}

/// `index.html`, generated from `video.json` and `theme.css`.
pub fn generate_index(meta: &VideoMeta, theme_css: &str) -> String {
    let (width, height) = meta.aspect.size();
    let total = meta.duration();
    let declarations = escape_html(&variable_declarations(meta).to_string());
    let values = escape_html(&variable_values(meta).to_string());
    let colors: String = meta
        .variables
        .iter()
        .filter(|v| v.kind == VariableKind::Color && valid_color(&v.value))
        .map(|v| format!("--{}:{};", v.id, v.value))
        .collect();
    let mut hosts = String::new();
    for (scene, start) in meta.scenes.iter().zip(meta.starts()) {
        hosts.push_str(&format!(
            "    <div id=\"{id}\" data-composition-id=\"{id}\" data-composition-src=\"compositions/{id}.html\" data-start=\"{start}\" data-duration=\"{duration}\" data-track-index=\"0\" data-width=\"{width}\" data-height=\"{height}\" data-variable-values=\"{values}\"></div>\n",
            id = scene.id,
            start = fmt_seconds(start),
            duration = fmt_seconds(scene.duration),
        ));
    }
    if let Some(voice) = &meta.audio.voice {
        hosts.push_str(&audio_clip("voiceover", voice, total, 1));
    }
    if let Some(music) = &meta.audio.music {
        hosts.push_str(&audio_clip("music", music, total, 2));
    }
    format!(
        "<!doctype html>\n\
<html data-composition-variables=\"{declarations}\">\n\
<head>\n\
<meta charset=\"utf-8\">\n\
<title>{title}</title>\n\
<style id=\"hf-base\">html,body{{margin:0;padding:0;background:#000;width:{width}px;height:{height}px;overflow:hidden}}#root{{position:relative;width:{width}px;height:{height}px;overflow:hidden}}</style>\n\
<style id=\"hf-vars\">:root{{{colors}}}</style>\n\
<style id=\"hf-theme\">\n{theme}\n</style>\n\
</head>\n\
<body>\n\
  <div id=\"root\" data-composition-id=\"main\" data-start=\"0\" data-duration=\"{total}\" data-width=\"{width}\" data-height=\"{height}\" data-fps=\"{fps}\" data-no-timeline>\n\
{hosts}  </div>\n\
</body>\n\
</html>\n",
        title = escape_html(&meta.title),
        theme = theme_css.trim(),
        total = fmt_seconds(total),
        fps = meta.fps,
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    pub(crate) const SCENE: &str = "<template id=\"intro-template\">\n<style>\n#root{position:absolute;inset:0;background:var(--bg)}\n.intro-title{animation:intro-up .8s ease both}\n@keyframes intro-up{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}\n</style>\n<div id=\"root\" data-composition-id=\"intro\" data-width=\"1920\" data-height=\"1080\">\n<div id=\"intro-card\" class=\"clip\" data-start=\"0\" data-duration=\"3\"><h1 id=\"intro-title\" class=\"intro-title\" data-var-text=\"headline\">Hola</h1><img id=\"intro-logo\" src=\"assets/logo.png\" data-var-src=\"logo\" alt=\"\"></div>\n</div>\n</template>";

    fn meta() -> VideoMeta {
        let mut meta = VideoMeta::new("Lanzamiento", Aspect::Landscape, 30);
        meta.scenes = vec![
            Scene {
                id: "intro".into(),
                title: "Intro".into(),
                duration: 3.0,
            },
            Scene {
                id: "outro".into(),
                title: "Cierre".into(),
                duration: 2.5,
            },
        ];
        meta.variables = vec![
            Variable {
                id: "headline".into(),
                kind: VariableKind::Text,
                label: "Titular".into(),
                value: "Hola & \"adiós\"".into(),
            },
            Variable {
                id: "bg".into(),
                kind: VariableKind::Color,
                label: "Fondo".into(),
                value: "#101820".into(),
            },
            Variable {
                id: "logo".into(),
                kind: VariableKind::Image,
                label: "Logo".into(),
                value: "assets/logo.png".into(),
            },
        ];
        meta
    }

    fn assets(path: &str) -> bool {
        matches!(
            path,
            "assets/logo.png" | "assets/voice.wav" | "assets/music.mp3"
        )
    }

    #[test]
    fn aspects_map_to_the_contract_canvases() {
        assert_eq!(Aspect::parse("16:9").map(Aspect::size), Some((1920, 1080)));
        assert_eq!(Aspect::parse("9:16").map(Aspect::size), Some((1080, 1920)));
        assert_eq!(Aspect::parse("1:1").map(Aspect::size), Some((1080, 1080)));
        assert_eq!(Aspect::parse("4:3"), None);
        assert_eq!(
            serde_json::to_string(&Aspect::Portrait).unwrap(),
            "\"9:16\""
        );
    }

    #[test]
    fn ids_are_short_lowercase_and_never_reserved() {
        for ok in ["intro", "scene-2", "a", "kpi-1-2"] {
            assert!(valid_id(ok), "{ok}");
        }
        for bad in [
            "",
            "Intro",
            "1intro",
            "intro-",
            "in_tro",
            "main",
            "root",
            "music",
            "voiceover",
            "a b",
            "../x",
            &"a".repeat(33),
        ] {
            assert!(!valid_id(bad), "{bad}");
        }
    }

    #[test]
    fn asset_paths_are_flat_named_and_typed() {
        for ok in [
            "assets/logo.png",
            "assets/voice-over.wav",
            "assets/fonts/inter-700.woff2",
            "assets/clip_1.mp4",
        ] {
            assert!(valid_asset_path(ok), "{ok}");
        }
        for bad in [
            "logo.png",
            "/assets/logo.png",
            "assets/../x.png",
            "assets/sub/x.png",
            "assets/x.exe",
            "assets/X.png",
            "assets/.png",
            "assets/a.b.png",
            "assets/fonts/x.png",
            "assets/x.html",
            "assets/",
            "compositions/intro.html",
        ] {
            assert!(!valid_asset_path(bad), "{bad}");
        }
    }

    #[test]
    fn a_css_only_scene_passes_and_is_normalized() {
        let out = validate_scene("intro", SCENE).expect("valid");
        assert!(out.starts_with("<template id=\"intro-template\">"));
        assert!(out.contains("data-composition-id=\"intro\" data-no-timeline"));
        // Idempotent.
        assert_eq!(validate_scene("intro", &out).expect("again"), out);
        // A template with the wrong id (or none) is rewritten to the right one.
        let other = SCENE.replace("<template id=\"intro-template\">", "<template class=\"x\">");
        assert!(
            validate_scene("intro", &other)
                .unwrap()
                .starts_with("<template id=\"intro-template\">")
        );
    }

    #[test]
    fn scenes_without_template_or_root_are_refused_with_guidance() {
        let err = validate_scene("intro", "<div data-composition-id=\"intro\"></div>").unwrap_err();
        assert!(err.contains("<template"), "{err}");
        let err = validate_scene(
            "intro",
            "<template><div id=\"root\" data-composition-id=\"other\"></div></template>",
        )
        .unwrap_err();
        assert!(err.contains("data-composition-id=\"intro\""), "{err}");
        let err = validate_scene("Intro", SCENE).unwrap_err();
        assert!(err.contains("invalid"), "{err}");
        assert!(validate_scene("intro", "  ").is_err());
        assert!(validate_scene("intro", &format!("{SCENE}{SCENE}")).is_err());
    }

    #[test]
    fn scenes_that_load_anything_or_break_determinism_are_refused() {
        let wrap = |body: &str| {
            format!(
                "<template><div id=\"root\" data-composition-id=\"intro\">{body}</div></template>"
            )
        };
        for body in [
            "<img src=\"https://x.io/a.png\">",
            "<img src=\"/etc/passwd\">",
            "<img src=\"../secret.png\">",
            "<img src=\"file:///etc/passwd\">",
            "<script src=\"assets/x.js\"></script>",
            "<script type=\"module\">1</script>",
            "<link rel=\"stylesheet\" href=\"assets/x.css\">",
            "<iframe srcdoc=\"x\"></iframe>",
            "<style>@import url(assets/a.css);</style>",
            "<style>.a{background:url(https://x.io/a.png)}</style>",
            "<style>@font-face{src:url(fonts/x.woff2)}</style>",
            "<style>.a{animation:spin 1s linear infinite}</style>",
            "<div style=\"animation: spin 1s infinite\"></div>",
            "<script>gsap.to('.a',{x:1})</script>",
            "<script>const t = Date.now()</script>",
            "<script>Math.random()</script>",
            "<script>setTimeout(f, 10)</script>",
            "<script>requestAnimationFrame(f)</script>",
            "<script>fetch('assets/a.json')</script>",
            "<script>document.getElementById('v').play()</script>",
            "<audio src=\"assets/music.mp3\"></audio>",
            "<audio id=\"a\" src=\"assets/music.mp3\" autoplay></audio>",
            "<video src=\"assets/clip.mp4\"></video>",
            "<img src=\"assets/a.png\" crossorigin=\"anonymous\">",
            "<button onclick=\"x()\">x</button>",
            "<meta http-equiv=\"refresh\" content=\"0\">",
        ] {
            assert!(
                validate_scene("intro", &wrap(body)).is_err(),
                "should refuse: {body}"
            );
        }
    }

    #[test]
    fn local_media_fonts_and_seeded_scripts_pass() {
        let body = "<style>@font-face{font-family:'Inter';src:url('assets/fonts/inter-700.woff2') format('woff2')}\
            .a{background:url(assets/bg.jpg) center/cover;animation:pop .4s ease 2 both}</style>\
            <video id=\"v\" class=\"clip\" src=\"assets/clip.mp4\" muted playsinline data-start=\"0\" data-duration=\"2\"></video>\
            <audio id=\"sfx\" class=\"clip\" src=\"./assets/pop.mp3\" data-start=\"1\" data-volume=\"0.5\"></audio>\
            <img src=\"data:image/png;base64,AAAA\" alt=\"\">\
            <script>function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;return 1}}\
            const rand = mulberry32(7); document.getElementById('v').animate([{opacity:0},{opacity:1}],{duration:500,fill:'both'}).pause();</script>";
        let html = format!(
            "<template><div id=\"root\" data-composition-id=\"intro\" data-no-timeline>{body}</div></template>"
        );
        validate_scene("intro", &html).expect("valid");
    }

    #[test]
    fn theme_css_is_plain_local_finite_css() {
        assert_eq!(validate_theme("  ").unwrap(), "");
        validate_theme(
            "@font-face{font-family:'Inter';src:url(assets/fonts/inter-400.woff2)}:root{--x:1}",
        )
        .expect("ok");
        for bad in [
            "@import url(assets/a.css);",
            ".a{background:url(https://x.io/a.png)}",
            "</style><script>alert(1)</script>",
            ".a{animation:a 1s infinite}",
        ] {
            assert!(validate_theme(bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn values_are_checked_per_kind() {
        assert_eq!(
            check_value(VariableKind::Color, " #FF5A1F ", &assets).unwrap(),
            "#ff5a1f"
        );
        assert!(check_value(VariableKind::Color, "red; background:url(x)", &assets).is_err());
        assert!(check_value(VariableKind::Text, &"a".repeat(MAX_TEXT_CHARS + 1), &assets).is_err());
        assert_eq!(
            check_value(VariableKind::Text, "Hola <b>", &assets).unwrap(),
            "Hola <b>"
        );
        assert_eq!(check_value(VariableKind::Image, "", &assets).unwrap(), "");
        assert!(check_value(VariableKind::Image, "assets/logo.png", &assets).is_ok());
        assert!(check_value(VariableKind::Image, "assets/missing.png", &assets).is_err());
        assert!(check_value(VariableKind::Image, "assets/voice.wav", &assets).is_err());
        assert!(check_value(VariableKind::Image, "https://x.io/a.png", &assets).is_err());
    }

    #[test]
    fn meta_limits_are_enforced() {
        let ok = meta();
        validate_meta(&ok, &assets).expect("valid");
        assert_eq!(ok.duration(), 5.5);
        assert_eq!(ok.starts(), vec![0.0, 3.0]);

        let mut long = meta();
        long.scenes = (0..6)
            .map(|i| Scene {
                id: format!("s{i}"),
                title: String::new(),
                duration: 110.0,
            })
            .collect();
        assert!(validate_meta(&long, &assets).unwrap_err().contains("600"));

        let mut dup = meta();
        dup.scenes[1].id = "intro".into();
        assert!(validate_meta(&dup, &assets).is_err());

        let mut short = meta();
        short.scenes[0].duration = 0.1;
        assert!(validate_meta(&short, &assets).is_err());

        let mut fps = meta();
        fps.fps = 50;
        assert!(validate_meta(&fps, &assets).is_err());

        let mut empty = meta();
        empty.scenes.clear();
        assert!(validate_meta(&empty, &assets).is_err());

        let mut audio = meta();
        audio.audio.music = Some(AudioTrack {
            file: "assets/logo.png".into(),
            volume: 0.5,
            duration: None,
        });
        assert!(validate_meta(&audio, &assets).is_err());
        audio.audio.music = Some(AudioTrack {
            file: "assets/music.mp3".into(),
            volume: 1.5,
            duration: None,
        });
        assert!(validate_meta(&audio, &assets).is_err());
        audio.audio.music = Some(AudioTrack {
            file: "assets/music.mp3".into(),
            volume: 0.5,
            duration: None,
        });
        validate_meta(&audio, &assets).expect("valid music");
    }

    #[test]
    fn video_json_round_trips_and_rejects_unknown_fields() {
        let json = serde_json::to_string(&meta()).unwrap();
        assert!(json.contains("\"aspect\":\"16:9\""));
        assert!(json.contains("\"type\":\"color\""));
        let back: VideoMeta = serde_json::from_str(&json).unwrap();
        assert_eq!(back, meta());
        let bad = json.replacen("\"fps\"", "\"evil\":1,\"fps\"", 1);
        assert!(serde_json::from_str::<VideoMeta>(&bad).is_err());
    }

    #[test]
    fn the_generated_index_wires_root_hosts_variables_and_audio() {
        let mut m = meta();
        m.audio.voice = Some(AudioTrack {
            file: "assets/voice.wav".into(),
            volume: 1.0,
            duration: Some(9.0),
        });
        m.audio.music = Some(AudioTrack {
            file: "assets/music.mp3".into(),
            volume: 0.4,
            duration: None,
        });
        let html = generate_index(&m, ":root{--x:1}");
        assert!(html.starts_with("<!doctype html>"));
        assert!(html.contains("<div id=\"root\" data-composition-id=\"main\" data-start=\"0\" data-duration=\"5.5\" data-width=\"1920\" data-height=\"1080\" data-fps=\"30\" data-no-timeline>"));
        assert!(html.contains("<div id=\"intro\" data-composition-id=\"intro\" data-composition-src=\"compositions/intro.html\" data-start=\"0\" data-duration=\"3\""));
        assert!(html.contains("<div id=\"outro\" data-composition-id=\"outro\" data-composition-src=\"compositions/outro.html\" data-start=\"3\" data-duration=\"2.5\""));
        // Values are escaped inside attributes, never raw.
        assert!(html.contains("Hola &amp; \\&quot;adiós\\&quot;"));
        assert!(!html.contains("Hola & \"adiós\""));
        assert!(html.contains(":root{--bg:#101820;}"));
        assert!(html.contains("&quot;type&quot;:&quot;image&quot;"));
        // The voice is cut at the video's end; music lasts the whole video.
        assert!(html.contains("<audio id=\"voiceover\" class=\"clip\" src=\"assets/voice.wav\" data-start=\"0\" data-duration=\"5.5\""));
        assert!(html.contains("<audio id=\"music\" class=\"clip\" src=\"assets/music.mp3\" data-start=\"0\" data-duration=\"5.5\" data-track-index=\"2\" data-volume=\"0.4\">"));
        assert!(html.contains("<style id=\"hf-theme\">\n:root{--x:1}\n</style>"));
        let titled = VideoMeta {
            title: "</title><script>x</script>".into(),
            ..meta()
        };
        assert!(!generate_index(&titled, "").contains("<script>x"));
    }

    #[test]
    fn seconds_print_without_float_noise() {
        assert_eq!(fmt_seconds(3.0), "3");
        assert_eq!(fmt_seconds(0.1 + 0.2), "0.3");
        assert_eq!(fmt_seconds(2.5), "2.5");
        assert_eq!(fmt_seconds(0.0), "0");
        assert_eq!(fmt_seconds(1.0005), "1.001");
    }
}
